package edu.pe.cibertec.saibm.membresia.migration;
import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test; import edu.pe.cibertec.saibm.membresia.infrastructure.migration.*;
class MembershipBackfillTest { @Test void mapperPreservesLegacyAliasesAndUsesExplicitOperatorLimitMap(){var m=new MembershipBackfillMapper(Map.of("premium",2,"super premium",4,"super premium plus",8,"estándar",2));var p=m.plan(new LegacyMembershipRow(3,"Super Premium"));assertThat(p.legacyId()).isEqualTo(3);assertThat(p.reservationLimit()).isEqualTo(4);assertThat(m.assignment(new LegacyUserMembershipRow(44,3)).legacyUserId()).isEqualTo(44);} @Test void reconcilerReportsMissingLegacyAliases(){var r=new MembershipBackfillReconciler().reconcile(List.of(new MembershipBackfillPlan(1,"a","A",2)),List.of(2),List.of(new MembershipBackfillAssignment(7,1)),List.of());assertThat(r.reconciled()).isFalse();assertThat(r.mismatches()).contains("missing plan 1","missing assignment 7");} }
